def complete(root, prefix):
    node = root
    for ch in prefix:                       # 1. walk to the prefix's node
        node = node.children.get(ch)
        if node is None:
            return []
    out = []
    def dfs(node, path):                    # 2. collect everything below
        if node.end:
            out.append(path)
        for ch in sorted(node.children):    # sorted -> alphabetical
            dfs(node.children[ch], path + ch)
    dfs(node, prefix)
    return out

def matches(node, pattern, i=0):
    """True if some word matches; '.' is any one letter."""
    if i == len(pattern):
        return node.end
    if pattern[i] == ".":
        return any(matches(c, pattern, i + 1) for c in node.children.values())
    child = node.children.get(pattern[i])
    return child is not None and matches(child, pattern, i + 1)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))    # everyone is their own root
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])   # compress
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False                # already in the same group
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra             # make ra the taller tree
        self.parent[rb] = ra            # shorter tree goes under
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1          # equal heights: one taller
        return True

def make_dsu(n):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        parent[rb] = ra
        return True
    return find, union

