from collections import deque
DIRS = [(1, 0), (-1, 0), (0, 1), (0, -1)]

def count_islands(grid):
    rows, cols = len(grid), len(grid[0])
    seen, islands = set(), 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in seen:
                islands += 1              # a new component
                seen.add((r, c))
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in DIRS:
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < rows and 0 <= nc < cols
                                and grid[nr][nc] == 1 and (nr, nc) not in seen):
                            seen.add((nr, nc))   # mark on enqueue
                            queue.append((nr, nc))
    return islands

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = OrderedDict()           # oldest first

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)          # just used: newest
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        elif len(self.data) == self.capacity:
            self.data.popitem(last=False)   # evict the oldest
        self.data[key] = value

